```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

fn parse_urls(raw: &str) -> Vec<String> {
    raw.split(|c: char| {
        c.is_whitespace()
            || matches!(c, ',' | ';' | '"' | '\'' | '[' | ']' | '{' | '}')
    })
    .map(|t| t.trim())
    .filter(|t| t.contains("://"))
    .map(|t| t.to_string())
    .collect()
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();
        for key in ["urls", "subscriptions", "feeds"] {
            if let Some(raw) = state_read::get(key) {
                urls = parse_urls(&raw);
                if !urls.is_empty() {
                    break;
                }
            }
        }
        SubscriptionList { urls }
    }
}

export!(Node);
